d = fitz.open('eprint/HAYSTAC_PIIExc.pdf')
p = d[0]
for b in p.get_text('dict')['blocks']:
    for l in b.get('lines',[]):
        for s in l['spans']:
            t=s['text'].strip()
            if t:
                x0,y0,x1,y1=s['bbox']
