"

python3 << 'EOF'
import fitz, numpy as np
d = fitz.open('eprint/HAYSTAC_PIIExc.pdf')
p = d[0]
dr = p.get_drawings()
purple=(0.7372549176216125, 0.07450980693101883, 0.9960784316062927)

pts=[]
for x in dr:
    if x.get('fill')==purple or x.get('color')==purple:
        r=x['rect']
        if r.y1>240 and r.x0>60 and r.x1<625:  # bottom-left zoom panel
            for it in x['items']:
                if it[0]=='l':
                    for pt in (it[1],it[2]):
                        if 235<pt.y<380: pts.append((pt.x,pt.y))
                elif it[0]=='c':
                    for pt in it[1:]:
                        if 235<pt.y<380: pts.append((pt.x,pt.y))
pts=np.array(sorted(set(pts)))
print('npts',len(pts), pts[:,0].min(), pts[:,0].max(), pts[:,1].min(), pts[:,1].max())

# calibration
mass = 17.0 + (pts[:,0]-108.0)*0.5/95.7   # micro-eV
gr   = (375.79 - pts[:,1])/16.575          # |g/gKSVZ|
print('mass range', mass.min(), mass.max())
print('g ratio range', gr.min(), gr.max())

# find gaps in mass coverage
ms = np.sort(np.unique(mass))
dm = np.diff(ms)
big = np.where(dm>0.02)[0]
print('gaps:')
for i in big: print('  ', round(ms[i],3),'->',round(ms[i+1],3))
np.save('pts.npy', np.column_stack([mass,gr]))
EOF
